import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    urls = re.findall(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', myString)
    domains = set()
    for url in urls:
        parsed_url = urllib.parse.urlparse(url)
        domains.add(parsed_url.netloc)

    geolocation_data = {}
    for domain in domains:
        try:
            response = requests.get(f"http://api.ipapi.com/api/{domain}?access_key={API_KEY}")
            response.raise_for_status()
            geolocation_data[domain] = response.json()
        except requests.exceptions.RequestException:
            geolocation_data[domain] = None
    return geolocation_data

