import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    data = json.loads(json_str)
    url_pattern = r'https?://[^\s<>"]+|www\.[^\s<>"]+'
    urls = []

    def find_urls_in_data(obj):
        if isinstance(obj, str):
            urls.extend(re.findall(url_pattern, obj))
        elif isinstance(obj, dict):
            for value in obj.values():
                find_urls_in_data(value)
        elif isinstance(obj, list):
            for item in obj:
                find_urls_in_data(item)

    find_urls_in_data(data)
    url_counts = Counter(urls)
    return dict(url_counts.most_common(top_n))

