import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, headers=HEADERS, params=parameters)
        response.raise_for_status()
        data = json.loads(response.text)
    except requests.exceptions.RequestException as e:
        raise Exception(f"URL cannot be accessed or invalid: {e}")
    except json.JSONDecodeError:
        raise Exception("Invalid data received from API: Malformed JSON")

    if not data:
        raise Exception("Empty data received from API")

    df = pd.DataFrame(data)

    numeric_df = df.select_dtypes(include=['number'])

    if numeric_df.empty:
        raise Exception("No numerical data found for correlation analysis")

    correlation_matrix = numeric_df.corr()

    ax = sns.heatmap(correlation_matrix, annot=True, cmap='coolwarm')
    return df, ax

