import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("The JSON data is malformed.")

    if not data:
        raise ValueError("The JSON data is empty.")

    processed_data = []
    for entry in data:
        country = entry.get('Country')
        population = entry.get('Population')

        if not isinstance(country, str):
            raise ValueError("Country name must be a string.")
        if not (isinstance(population, (int, float)) and population >= 0):
            raise ValueError("Population must be a non-negative number.")

        processed_data.append({'Country': country, 'Population': math.floor(population)})

    df = pd.DataFrame(processed_data)

    output_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(output_path, index=False)
    except IOError:
        raise IOError("The file cannot be written to the specified directory.")

    return output_path, df

